using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using Microsoft.AspNetCore.Identity;
using Microsoft.Extensions.Options;
using RoadGuardSystem.aBusinessObjects.Commons;
using RoadGuardSystem.BusinessObjects.Identity;
using RoadGuardSystem.Repositories.Identity;
using RoadGuardSystem.Services.Factories;
using RoadGuardSystem.Services.Options;

namespace RoadGuardSystem.Services.Authentication;

public sealed class IdentityOnboardingService : IIdentityOnboardingService
{
    private readonly IIdentityOnboardingRepository _onboardingRepository;
    private readonly IIdentityRepository _identityRepository;
    private readonly IPasswordHasher<ApplicationUser> _passwordHasher;
    private readonly UserManager<ApplicationUser> _userManager;
    private readonly IIdentityMessageSender _messageSender;
    private readonly AccessTokenFactory _accessTokenFactory;
    private readonly JwtOptions _jwtOptions;
    private readonly IdentityOnboardingOptions _options;
    private readonly TimeProvider _timeProvider;
    private readonly byte[] _secret;

    public IdentityOnboardingService(
        IIdentityOnboardingRepository onboardingRepository,
        IIdentityRepository identityRepository,
        IPasswordHasher<ApplicationUser> passwordHasher,
        UserManager<ApplicationUser> userManager,
        IIdentityMessageSender messageSender,
        AccessTokenFactory accessTokenFactory,
        IOptions<JwtOptions> jwtOptions,
        IOptions<IdentityOnboardingOptions> options,
        TimeProvider timeProvider)
    {
        _onboardingRepository = onboardingRepository;
        _identityRepository = identityRepository;
        _passwordHasher = passwordHasher;
        _userManager = userManager;
        _messageSender = messageSender;
        _accessTokenFactory = accessTokenFactory;
        _jwtOptions = jwtOptions.Value;
        _options = options.Value;
        _timeProvider = timeProvider;
        _secret = DecodeSecret(_options.Secret);
    }

    public async Task<IdentityOnboardingResult> RegisterReporterAsync(
        string email,
        string password,
        string displayName,
        string reporterType,
        string idempotencyKey,
        CancellationToken cancellationToken = default)
    {
        if (!TryNormalizeEmail(email, out var normalizedEmail) || string.IsNullOrWhiteSpace(password) ||
            string.IsNullOrWhiteSpace(displayName) || string.IsNullOrWhiteSpace(idempotencyKey) ||
            !TryParseReporterType(reporterType, out var parsedReporterType))
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.InvalidInput);
        }

        if (!await ValidatePasswordAsync(new ApplicationUser { UserName = email.Trim(), Email = email.Trim() }, password, cancellationToken))
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.InvalidInput);
        }

        var operationId = OperationId("RegisterReporter", idempotencyKey);
        var userId = Guid.NewGuid();
        var intentId = Guid.NewGuid();
        var otp = NumericSecret("reporter-otp", operationId);
        var now = _timeProvider.GetUtcNow();
        var user = new ApplicationUser
        {
            Id = userId,
            UserName = email.Trim(),
            NormalizedUserName = normalizedEmail,
            Email = email.Trim(),
            NormalizedEmail = normalizedEmail,
            EmailConfirmed = false,
            DisplayName = displayName.Trim(),
            RoleCode = UserRoleCode.Reporter,
            Status = UserStatus.Pending,
            SecurityStamp = Guid.NewGuid().ToString("N"),
            CreatedAt = now
        };
        user.PasswordHash = _passwordHasher.HashPassword(user, password);
        var intent = new ReporterRegistrationIntent
        {
            Id = intentId,
            UserId = userId,
            NormalizedEmail = normalizedEmail,
            ReporterType = parsedReporterType,
            OtpHash = HashSecret(otp),
            OtpGeneration = 1,
            ExpiresAt = now.AddMinutes(_options.OtpLifetimeMinutes),
            ResendAvailableAt = now.AddSeconds(_options.OtpResendCooldownSeconds),
            CreatedAt = now
        };
        var fingerprint = HashSecret($"{normalizedEmail}|{displayName.Trim()}|{parsedReporterType}|{password}");
        var persisted = await _onboardingRepository.RegisterReporterAsync(
            user,
            intent,
            idempotencyKey.Trim(),
            fingerprint,
            operationId,
            cancellationToken);
        if (persisted.Status == IdentityOnboardingPersistenceStatus.Success && persisted.Intent is not null)
        {
            if (!await _messageSender.SendReporterOtpAsync(email.Trim(), otp, cancellationToken))
            {
                return new IdentityOnboardingResult(IdentityOnboardingStatus.DeliveryUnavailable, ToView(persisted.Intent));
            }

            return new IdentityOnboardingResult(Map(persisted.Status), ToView(persisted.Intent));
        }

        return new IdentityOnboardingResult(Map(persisted.Status));
    }

    public async Task<IdentityOnboardingResult> VerifyReporterOtpAsync(
        Guid intentId,
        string otp,
        string idempotencyKey,
        CancellationToken cancellationToken = default)
    {
        if (intentId == Guid.Empty || string.IsNullOrWhiteSpace(otp) || string.IsNullOrWhiteSpace(idempotencyKey))
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.InvalidInput);
        }

        var intent = await _onboardingRepository.GetReporterRegistrationIntentAsync(intentId, cancellationToken);
        if (intent?.UserId is null)
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.NotFound);
        }

        var operationId = OperationId("VerifyReporterOtp", idempotencyKey);
        var credentials = CreateCredentials(intent.UserId.Value, operationId, "reporter-verify", UserRoleCode.Reporter);
        var fingerprint = HashSecret($"{intentId:N}|{otp}");
        var persisted = await _onboardingRepository.VerifyReporterOtpAsync(
            intentId,
            HashSecret(otp),
            _options.OtpMaxAttempts,
            credentials.Session,
            credentials.RefreshToken,
            idempotencyKey.Trim(),
            fingerprint,
            operationId,
            credentials.IssuedAt,
            cancellationToken);
        return persisted.User is not null && persisted.SessionId is not null &&
               persisted.Status is IdentityOnboardingPersistenceStatus.Success or IdentityOnboardingPersistenceStatus.IdempotentReplay
            ? new IdentityOnboardingResult(
                Map(persisted.Status),
                ToView(persisted.Intent),
                Tokens: CreateTokens(persisted.User, persisted.SessionId.Value, operationId, "reporter-verify"))
            : new IdentityOnboardingResult(Map(persisted.Status), ToView(persisted.Intent));
    }

    public async Task<IdentityOnboardingResult> ResendReporterOtpAsync(
        Guid intentId,
        string idempotencyKey,
        CancellationToken cancellationToken = default)
    {
        if (intentId == Guid.Empty || string.IsNullOrWhiteSpace(idempotencyKey))
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.InvalidInput);
        }

        var operationId = OperationId("ResendReporterOtp", idempotencyKey);
        var otp = NumericSecret("reporter-resend", operationId);
        var now = _timeProvider.GetUtcNow();
        var persisted = await _onboardingRepository.ResendReporterOtpAsync(
            intentId,
            HashSecret(otp),
            now.AddMinutes(_options.OtpLifetimeMinutes),
            now.AddSeconds(_options.OtpResendCooldownSeconds),
            _options.OtpMaxResendsPerWindow,
            TimeSpan.FromMinutes(_options.OtpResendWindowMinutes),
            idempotencyKey.Trim(),
            HashSecret(intentId.ToString("N")),
            operationId,
            now,
            cancellationToken);
        if (persisted.Status == IdentityOnboardingPersistenceStatus.Success &&
            persisted.Intent is not null &&
            !await _messageSender.SendReporterOtpAsync(persisted.Intent.NormalizedEmail, otp, cancellationToken))
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.DeliveryUnavailable, ToView(persisted.Intent));
        }

        return new IdentityOnboardingResult(Map(persisted.Status), ToView(persisted.Intent));
    }

    public async Task<IdentityOnboardingResult> CreateInvitationAsync(
        Guid actorUserId,
        string email,
        string role,
        IReadOnlyList<Guid> projectIds,
        string idempotencyKey,
        CancellationToken cancellationToken = default)
    {
        var actor = await _identityRepository.GetUserSecurityStateAsync(actorUserId, cancellationToken);
        if (actor is not { Status: UserStatus.Active, RoleCode: UserRoleCode.Supervisor })
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.Forbidden);
        }

        if (!TryNormalizeEmail(email, out var normalizedEmail) ||
            !TryParseStaffRole(role, out var roleCode) ||
            projectIds is null || projectIds.Distinct().Count() != projectIds.Count ||
            string.IsNullOrWhiteSpace(idempotencyKey))
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.InvalidInput);
        }

        var operationId = OperationId("CreateInvitation", $"{actorUserId:N}:{idempotencyKey}");
        var invitationId = Guid.NewGuid();
        var token = Convert.ToBase64String(RandomNumberGenerator.GetBytes(32))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_');
        var now = _timeProvider.GetUtcNow();
        var invitation = new StaffInvitation
        {
            Id = invitationId,
            DisplayName = email.Trim(),
            Email = email.Trim(),
            NormalizedEmail = normalizedEmail,
            RoleCode = roleCode,
            TokenHash = HashSecret(token),
            CreatedByUserId = actorUserId,
            CreatedAt = now,
            ExpiresAt = now.AddHours(_options.InvitationLifetimeHours)
        };
        var fingerprint = HashSecret($"{normalizedEmail}|{roleCode}|{string.Join(',', projectIds.Order())}");
        var persisted = await _onboardingRepository.CreateInvitationAsync(
            invitation,
            projectIds,
            idempotencyKey.Trim(),
            fingerprint,
            operationId,
            cancellationToken);
        if (persisted.Status is IdentityOnboardingPersistenceStatus.Success &&
             persisted.Invitation is not null &&
             !await _messageSender.SendInvitationAsync(
                email.Trim(),
                persisted.Invitation.DisplayName,
                DisplayRoleName(persisted.Invitation.RoleCode),
                persisted.DeliveryToken ?? token,
                persisted.Invitation.ExpiresAt,
                cancellationToken))
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.DeliveryUnavailable, Invitation: ToView(persisted.Invitation));
        }

        return new IdentityOnboardingResult(Map(persisted.Status), Invitation: ToView(persisted.Invitation));
    }

    public async Task<IdentityOnboardingResult> AcceptInvitationAsync(
        string invitationToken,
        string displayName,
        string password,
        string idempotencyKey,
        CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(invitationToken) || string.IsNullOrWhiteSpace(displayName) ||
            string.IsNullOrWhiteSpace(password) || string.IsNullOrWhiteSpace(idempotencyKey))
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.InvalidInput);
        }

        var tokenHash = HashSecret(invitationToken);
        var invitation = await _onboardingRepository.GetInvitationByTokenHashAsync(tokenHash, cancellationToken);
        if (invitation is null)
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.NotFound);
        }

        if (!await ValidatePasswordAsync(new ApplicationUser { UserName = invitation.Email, Email = invitation.Email }, password, cancellationToken))
        {
            return new IdentityOnboardingResult(IdentityOnboardingStatus.InvalidInput);
        }

        var operationId = OperationId("AcceptInvitation", idempotencyKey);
        var user = new ApplicationUser
        {
            Id = Guid.NewGuid(),
            DisplayName = displayName.Trim(),
            Status = UserStatus.Active,
            EmailConfirmed = true,
            MustChangePassword = false,
            SecurityStamp = Guid.NewGuid().ToString("N"),
            CreatedAt = _timeProvider.GetUtcNow()
        };
        user.PasswordHash = _passwordHasher.HashPassword(user, password);
        var credentials = CreateCredentials(user.Id, operationId, "invitation-accept", invitation.RoleCode);
        var persisted = await _onboardingRepository.AcceptInvitationAsync(
            tokenHash,
            user,
            credentials.Session,
            credentials.RefreshToken,
            idempotencyKey.Trim(),
            HashSecret($"{tokenHash}|{displayName.Trim()}|{password}"),
            operationId,
            credentials.IssuedAt,
            cancellationToken);
        return persisted.User is not null && persisted.SessionId is not null &&
               persisted.Status is IdentityOnboardingPersistenceStatus.Success or IdentityOnboardingPersistenceStatus.IdempotentReplay
            ? new IdentityOnboardingResult(
                Map(persisted.Status),
                Invitation: ToView(persisted.Invitation),
                Tokens: CreateTokens(persisted.User, persisted.SessionId.Value, operationId, "invitation-accept"))
            : new IdentityOnboardingResult(Map(persisted.Status), Invitation: ToView(persisted.Invitation));
    }

    private (UserSession Session, RefreshToken RefreshToken, DateTimeOffset IssuedAt) CreateCredentials(
        Guid userId,
        Guid operationId,
        string purpose, UserRoleCode role)
    {
        var issuedAt = _timeProvider.GetUtcNow();
        var sessionId = OperationId($"{purpose}:session", operationId.ToString("N"));
        var refreshPlaintext = TokenSecret($"{purpose}:refresh", operationId);
        return (
            new UserSession
            {
                Id = sessionId,
                UserId = userId,
                IssuedAt = issuedAt,
                ExpiresAt = null,
                Lifecycle = SessionLifecycle.PersistentRenewable,
                IssuedRole = role
            },
            new RefreshToken
            {
                Id = OperationId($"{purpose}:refresh-id", operationId.ToString("N")),
                SessionId = sessionId,
                TokenHash = Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(refreshPlaintext))).ToLowerInvariant(),
                ExpiresAt = null
            },
            issuedAt);
    }

    private AuthTokens CreateTokens(UserSecurityState user, Guid sessionId, Guid operationId, string purpose)
    {
        var now = _timeProvider.GetUtcNow();
        return new AuthTokens(
            _accessTokenFactory.Create(user.Id, sessionId, user.RoleCode, now),
            TokenSecret($"{purpose}:refresh", operationId),
            now.AddMinutes(_jwtOptions.AccessTokenLifetimeMinutes),
            null,
            checked(_jwtOptions.AccessTokenLifetimeMinutes * 60),
            user);
    }

    private string NumericSecret(string purpose, Guid id)
    {
        var hash = HMACSHA256.HashData(_secret, Encoding.UTF8.GetBytes($"{purpose}:{id:N}"));
        var value = BitConverter.ToUInt32(hash, 0) % 1_000_000;
        return value.ToString("D6", CultureInfo.InvariantCulture);
    }

    private string TokenSecret(string purpose, Guid id) =>
        Convert.ToBase64String(HMACSHA256.HashData(_secret, Encoding.UTF8.GetBytes($"{purpose}:{id:N}")))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_');

    private string HashSecret(string value) =>
        Convert.ToHexString(HMACSHA256.HashData(_secret, Encoding.UTF8.GetBytes(value))).ToLowerInvariant();

    private Guid OperationId(string operation, string key)
    {
        var hash = HMACSHA256.HashData(_secret, Encoding.UTF8.GetBytes($"{operation}:{key.Trim()}"));
        return new Guid(hash[..16]);
    }

    private static byte[] DecodeSecret(string value)
    {
        try
        {
            var decoded = Convert.FromBase64String(value);
            if (decoded.Length >= 32)
            {
                return decoded;
            }
        }
        catch (FormatException)
        {
        }

        throw new OptionsValidationException(
            IdentityOnboardingOptions.SectionName,
            typeof(IdentityOnboardingOptions),
            ["IdentityOnboarding:Secret must be valid Base64 containing at least 32 bytes."]);
    }

    private static bool TryNormalizeEmail(string value, out string normalized)
    {
        normalized = value?.Trim().ToUpperInvariant() ?? string.Empty;
        return normalized.Length is > 3 and <= 254 && normalized.Count(character => character == '@') == 1;
    }

    private static bool TryParseReporterType(string value, out ReporterType reporterType)
    {
        reporterType = value?.Trim().ToUpperInvariant() switch
        {
            "CITIZEN" => ReporterType.Citizen,
            "INVESTOR_REPRESENTATIVE" => ReporterType.InvestorRepresentative,
            _ => ReporterType.Unknown
        };
        return reporterType != ReporterType.Unknown;
    }

    private static bool TryParseStaffRole(string value, out UserRoleCode role)
    {
        role = value?.Trim().ToUpperInvariant() switch
        {
            "SUPERVISOR" => UserRoleCode.Supervisor,
            "PM" => UserRoleCode.ProjectManager,
            "OPERATOR" => UserRoleCode.DroneOperator,
            "CREW" => UserRoleCode.RepairCrew,
            _ => UserRoleCode.Unknown
        };
        return role != UserRoleCode.Unknown;
    }

    private static string DisplayRoleName(UserRoleCode role) => role switch
    {
        UserRoleCode.Supervisor => "Supervisor",
        UserRoleCode.ProjectManager => "Project Manager",
        UserRoleCode.DroneOperator => "Drone Operator",
        UserRoleCode.RepairCrew => "Repair Crew",
        _ => role.ToString()
    };

    private static IdentityOnboardingStatus Map(IdentityOnboardingPersistenceStatus status) => status switch
    {
        IdentityOnboardingPersistenceStatus.Success => IdentityOnboardingStatus.Success,
        IdentityOnboardingPersistenceStatus.IdempotentReplay => IdentityOnboardingStatus.IdempotentReplay,
        IdentityOnboardingPersistenceStatus.IdempotentConflict => IdentityOnboardingStatus.IdempotencyConflict,
        IdentityOnboardingPersistenceStatus.Forbidden => IdentityOnboardingStatus.Forbidden,
        IdentityOnboardingPersistenceStatus.NotFound => IdentityOnboardingStatus.NotFound,
        IdentityOnboardingPersistenceStatus.Conflict => IdentityOnboardingStatus.Conflict,
        IdentityOnboardingPersistenceStatus.TooManyRequests => IdentityOnboardingStatus.TooManyRequests,
        _ => IdentityOnboardingStatus.InvalidInput
    };

    private RegistrationIntentView? ToView(ReporterRegistrationIntent? intent) => intent is null
        ? null
        : new RegistrationIntentView(
            intent.Id,
            Math.Max(0, (int)Math.Ceiling((intent.ResendAvailableAt - _timeProvider.GetUtcNow()).TotalSeconds)));

    private static InvitationView? ToView(StaffInvitation? invitation) => invitation is null
        ? null
        : new InvitationView(
            invitation.Id,
            invitation.AcceptedAt is null ? "PENDING" : "ACCEPTED",
            invitation.ExpiresAt,
            invitation.RowVersion);

    private async Task<bool> ValidatePasswordAsync(ApplicationUser user, string password, CancellationToken cancellationToken)
    {
        foreach (var validator in _userManager.PasswordValidators)
        {
            var validation = await validator.ValidateAsync(_userManager, user, password);
            if (!validation.Succeeded)
            {
                return false;
            }
        }

        cancellationToken.ThrowIfCancellationRequested();
        return true;
    }
}

using System.Security.Cryptography;
using System.Text;
using Microsoft.Extensions.Options;
using RoadGuardSystem.DTOs.Files;
using RoadGuardSystem.BusinessObjects.Files;
using RoadGuardSystem.Repositories.Files;
using RoadGuardSystem.Repositories.Options;
using RoadGuardSystem.Repositories.Storage;
using RoadGuardSystem.Services.Authorization;
using RoadGuardSystem.Services.Files;
using RoadGuardSystem.aBusinessObjects.Commons;

namespace RoadGuardSystem.Services.Implementations.Files;

public sealed class UploadService : IUploadService
{
    private static readonly HashSet<string> Purposes = new(StringComparer.Ordinal)
    {
        "REPORT_PHOTO", "BEFORE", "AFTER", "MEASUREMENT", "SURVEY_VIDEO", "TELEMETRY", "ROUTE_SOURCE", "DOCUMENT"
    };

    private readonly IUploadRepository _repository;
    private readonly IProjectScopeGuard _scopeGuard;
    private readonly TimeProvider _timeProvider;
    private readonly UploadSessionOptions _options;

    public UploadService(
        IUploadRepository repository,
        IProjectScopeGuard scopeGuard,
        TimeProvider timeProvider,
        IOptions<UploadSessionOptions> options)
    {
        _repository = repository;
        _scopeGuard = scopeGuard;
        _timeProvider = timeProvider;
        _options = options.Value;
    }

    public async Task<UploadServiceResult> CreateAsync(
        Guid actorUserId,
        UserRoleCode role,
        UploadCreateRequestDto request,
        string idempotencyKey,
        Guid? correlationId,
        CancellationToken cancellationToken = default)
        => await CreateCoreAsync(actorUserId, role, request, idempotencyKey, correlationId, null, cancellationToken);

    public Task<UploadServiceResult> CreateOfflineAsync(Guid actorUserId, UserRoleCode role,
        OfflineUploadCreateRequestDto request, string idempotencyKey, Guid? correlationId, CancellationToken cancellationToken = default)
    {
        if (request is null || request.AdmissionId == Guid.Empty || request.CaptureOriginId == Guid.Empty ||
            request.Upload is null || request.Upload.TargetId is null || !IsFieldPurpose(request.Upload.Purpose) ||
            role is not (UserRoleCode.ProjectManager or UserRoleCode.RepairCrew)) return Task.FromResult(new UploadServiceResult(UploadServiceStatus.InvalidInput));
        return CreateCoreAsync(actorUserId, role, request.Upload, idempotencyKey, correlationId, request, cancellationToken);
    }

    private async Task<UploadServiceResult> CreateCoreAsync(Guid actorUserId, UserRoleCode role,
        UploadCreateRequestDto request, string idempotencyKey, Guid? correlationId,
        OfflineUploadCreateRequestDto? offline, CancellationToken cancellationToken)
    {
        if (!IsSupportedRole(role) || !IsValidCreate(actorUserId, request, idempotencyKey) || !ValidOptions())
        {
            return new(UploadServiceStatus.InvalidInput);
        }

        if (!await InProjectScopeAsync(actorUserId, role, request.ProjectId!.Value, cancellationToken))
        {
            return new(UploadServiceStatus.Forbidden);
        }

        if (offline is null && IsFieldPurpose(request.Purpose) && (request.TargetId is not Guid fieldTask ||
            !await _repository.IsCurrentFieldActorAsync(actorUserId, role, request.ProjectId.Value, fieldTask, request.Purpose.Trim().ToUpperInvariant(), true, cancellationToken)))
            return new(UploadServiceStatus.Forbidden);

        if (IsSurveyPurpose(request.Purpose) && (role != UserRoleCode.DroneOperator || request.TargetId is not { } taskId ||
            !await _repository.IsCurrentSurveyOperatorAsync(actorUserId, request.ProjectId.Value, taskId, true, cancellationToken)))
            return new(UploadServiceStatus.Forbidden);

        var maximum = UploadAdmissionPolicy.MaximumBytes(request.Purpose, request.MediaType);
        if (maximum is null || request.SizeBytes > maximum)
            return new(UploadServiceStatus.InvalidInput, MaxBytes: maximum, ActualBytes: request.SizeBytes);

        var now = _timeProvider.GetUtcNow();
        var normalized = Normalize(request);
        var persistence = new UploadCreatePersistenceRequest(
            actorUserId,
            normalized.ProjectId!.Value,
            normalized.TargetId,
            normalized.Purpose,
            normalized.FileName,
            normalized.MediaType,
            normalized.SizeBytes,
            normalized.ChecksumSha256,
            _options.PartSizeBytes,
            now.AddHours(_options.SessionLifetimeHours),
            idempotencyKey.Trim(),
            Fingerprint($"{normalized.Purpose}|{normalized.ProjectId}|{normalized.TargetId}|{normalized.FileName}|{normalized.MediaType}|{normalized.SizeBytes}|{normalized.ChecksumSha256}"),
            correlationId);
        var result = offline is null ? await _repository.CreateAsync(persistence, cancellationToken) :
            await _repository.CreateOfflineAsync(new(normalized.ProjectId!.Value, normalized.TargetId!.Value,
                offline.AdmissionId, offline.CaptureOriginId, actorUserId, role,
                persistence with { RequestFingerprint = Fingerprint($"{persistence.RequestFingerprint}|{offline.AdmissionId:D}|{offline.CaptureOriginId:D}") }), cancellationToken);
        return MapMutation(result);
    }

    public async Task<UploadServiceResult> GetSessionAsync(Guid actorUserId, UserRoleCode role, Guid uploadId, CancellationToken cancellationToken = default)
    {
        var session = await _repository.GetSessionAsync(uploadId, cancellationToken);
        if (session is null) return new(UploadServiceStatus.NotFound);
        if (!await _repository.IsCurrentOfflineFileActorAsync(actorUserId, role, session.FileId, cancellationToken) &&
            !await CanAccessAssetAsync(actorUserId, role, session.ProjectId, session.Purpose, session.TargetId, false, cancellationToken)) return new(UploadServiceStatus.Forbidden);
        return new(UploadServiceStatus.Success, ToDto(session));
    }

    public async Task<UploadServiceResult> GetPartUrlsAsync(
        Guid actorUserId,
        UserRoleCode role,
        Guid uploadId,
        UploadPartUrlsRequestDto request,
        string idempotencyKey,
        CancellationToken cancellationToken = default)
    {
        if (string.IsNullOrWhiteSpace(idempotencyKey) || request?.PartNumbers is null) return new(UploadServiceStatus.InvalidInput);
        var session = await _repository.GetSessionAsync(uploadId, cancellationToken);
        if (session is null) return new(UploadServiceStatus.NotFound);
        if (!await _repository.IsCurrentOfflineFileActorAsync(actorUserId, role, session.FileId, cancellationToken) &&
            !await CanAccessAssetAsync(actorUserId, role, session.ProjectId, session.Purpose, session.TargetId, true, cancellationToken)) return new(UploadServiceStatus.Forbidden);
        var now = _timeProvider.GetUtcNow();
        var urlExpiresAt = now.AddMinutes(_options.SignedPutUrlLifetimeMinutes);
        if (urlExpiresAt > session.ExpiresAt)
        {
            urlExpiresAt = session.ExpiresAt;
        }

        var result = await _repository.GetPartUrlsAsync(
            actorUserId,
            session.ProjectId,
            uploadId,
            request.PartNumbers,
            idempotencyKey.Trim(),
            Fingerprint($"{uploadId:N}|{string.Join(',', request.PartNumbers.OrderBy(number => number))}"),
            now,
            urlExpiresAt,
            cancellationToken);
        return result.Status switch
        {
            UploadPersistenceStatus.Success or UploadPersistenceStatus.Replayed => new(
                result.Status == UploadPersistenceStatus.Replayed ? UploadServiceStatus.Replayed : UploadServiceStatus.Success,
                PartUrls: new(result.Parts.Select(part => new UploadPartUrlResponseDto(part.PartNumber, part.Url, part.ExpiresAt)).ToArray())),
            UploadPersistenceStatus.NotFound => new(UploadServiceStatus.NotFound),
            UploadPersistenceStatus.Conflict => new(UploadServiceStatus.Conflict),
            UploadPersistenceStatus.StorageUnavailable => new(UploadServiceStatus.StorageUnavailable),
            _ => new(UploadServiceStatus.InvalidInput)
        };
    }

    public async Task<UploadServiceResult> CompleteAsync(
        Guid actorUserId,
        UserRoleCode role,
        Guid uploadId,
        UploadCompleteRequestDto request,
        string idempotencyKey,
        string expectedVersion,
        Guid? correlationId,
        CancellationToken cancellationToken = default)
    {
        if (request?.Parts is null || string.IsNullOrWhiteSpace(idempotencyKey) || string.IsNullOrWhiteSpace(expectedVersion)) return new(UploadServiceStatus.InvalidInput);
        var session = await _repository.GetSessionAsync(uploadId, cancellationToken);
        if (session is null) return new(UploadServiceStatus.NotFound);
        if (!await _repository.IsCurrentOfflineFileActorAsync(actorUserId, role, session.FileId, cancellationToken) &&
            !await CanAccessAssetAsync(actorUserId, role, session.ProjectId, session.Purpose, session.TargetId, true, cancellationToken,
            requireActiveTask: session.Status is not ("VERIFYING" or "VERIFIED"))) return new(UploadServiceStatus.Forbidden);
        var result = await _repository.CompleteAsync(new UploadCompletePersistenceRequest(
            actorUserId,
            session.ProjectId,
            uploadId,
            expectedVersion.Trim().Trim('"'),
            request.Parts.Select(part => new CompletedStoragePart(part.PartNumber, part.ETag)).ToArray(),
            request.ChecksumSha256,
            idempotencyKey.Trim(),
            Fingerprint($"{uploadId:N}|{expectedVersion}|{request.ChecksumSha256}|{string.Join(',', request.Parts.OrderBy(part => part.PartNumber).Select(part => $"{part.PartNumber}:{part.ETag}"))}"),
            correlationId), cancellationToken);
        return MapMutation(result);
    }

    public async Task<UploadServiceResult> GetFileMetadataAsync(Guid actorUserId, UserRoleCode role, Guid fileId, CancellationToken cancellationToken = default)
    {
        var file = await _repository.GetFileMetadataAsync(fileId, cancellationToken);
        if (file is null) return new(UploadServiceStatus.NotFound);
        if (!await CanReadFileAsync(actorUserId, role, file, cancellationToken)) return new(UploadServiceStatus.Forbidden);
        return new(UploadServiceStatus.Success, File: ToDto(file));
    }

    public async Task<UploadServiceResult> DownloadAsync(Guid actorUserId, UserRoleCode role, Guid fileId, CancellationToken cancellationToken = default)
    {
        var file = await _repository.GetFileMetadataAsync(fileId, cancellationToken);
        if (file is null || file.Status != "VERIFIED") return new(UploadServiceStatus.NotFound);
        if (!await CanReadFileAsync(actorUserId, role, file, cancellationToken)) return new(UploadServiceStatus.Forbidden);
        try
        {
            var stream = await _repository.OpenFileAsync(file.ObjectKey, cancellationToken);
            if (IsFieldPurpose(file.Purpose))
            {
                try
                {
                    var fresh = await _repository.GetFileMetadataAsync(fileId, cancellationToken);
                    if (fresh is null || fresh.Status != "VERIFIED" || fresh.Version != file.Version ||
                        !await CanReadFileAsync(actorUserId, role, fresh, cancellationToken))
                    { await stream.DisposeAsync(); return new(UploadServiceStatus.Forbidden); }
                }
                catch { await stream.DisposeAsync(); throw; }
            }
            return new(UploadServiceStatus.Success, File: ToDto(file), Content: stream);
        }
        catch (FileStorageException)
        {
            return new(UploadServiceStatus.StorageUnavailable);
        }
    }

    public async Task ProcessOneVerificationAsync(CancellationToken cancellationToken = default)
    {
        await _repository.VerifyNextAsync(cancellationToken);
    }

    private async Task<bool> CanReadFileAsync(Guid actor, UserRoleCode role, FileMetadataPersistenceView file, CancellationToken token)
        => await _repository.IsCurrentOfflineFileActorAsync(actor, role, file.Id, token) || await CanAccessAssetAsync(actor, role, file.ProjectId, file.Purpose, file.TargetId, false, token) ||
            (file.ProjectId is Guid project && IsFieldPurpose(file.Purpose) && await _repository.IsCurrentLegacyFieldFileReaderAsync(actor, role, project, file.Id, file.Purpose!, token));

    private async Task<bool> CanAccessAssetAsync(Guid actorUserId, UserRoleCode role, Guid? projectId, string? purpose, Guid? targetId, bool mutation, CancellationToken cancellationToken, bool requireActiveTask = true)
    {
        if (projectId is not { } scopedProjectId || !IsSupportedRole(role) || !await InProjectScopeAsync(actorUserId, role, scopedProjectId, cancellationToken)) return false;
        if (IsFieldPurpose(purpose)) return targetId is Guid fieldTask &&
            await _repository.IsCurrentFieldActorAsync(actorUserId, role, scopedProjectId, fieldTask, purpose!.Trim().ToUpperInvariant(), mutation && requireActiveTask, cancellationToken);
        if (!IsSurveyPurpose(purpose)) return true;
        if (!mutation && role is UserRoleCode.Supervisor or UserRoleCode.ProjectManager) return true;
        return role == UserRoleCode.DroneOperator && targetId is { } taskId &&
            await _repository.IsCurrentSurveyOperatorAsync(actorUserId, scopedProjectId, taskId, mutation && requireActiveTask, cancellationToken);
    }

    private static bool IsFieldPurpose(string? purpose) => purpose?.Trim().ToUpperInvariant() is "BEFORE" or "AFTER" or "MEASUREMENT";

    private static bool IsSurveyPurpose(string? purpose) => purpose?.Trim().ToUpperInvariant() is "SURVEY_VIDEO" or "TELEMETRY";

    private async Task<bool> InProjectScopeAsync(Guid actorUserId, UserRoleCode role, Guid projectId, CancellationToken cancellationToken)
        => await _scopeGuard.AuthorizeAsync(actorUserId, role, projectId, cancellationToken) is not null;

    private static bool IsSupportedRole(UserRoleCode role)
        => role is UserRoleCode.Supervisor or UserRoleCode.ProjectManager or UserRoleCode.DroneOperator or UserRoleCode.RepairCrew;

    private static bool IsValidCreate(Guid actorUserId, UploadCreateRequestDto? request, string idempotencyKey)
        => actorUserId != Guid.Empty && request is not null && request.ProjectId is not null && request.ProjectId != Guid.Empty &&
           request.SizeBytes > 0 && !string.IsNullOrWhiteSpace(idempotencyKey) &&
           Purposes.Contains(request.Purpose?.Trim().ToUpperInvariant() ?? string.Empty) && ValidMimeType(request.MediaType) &&
           request.FileName is { Length: > 0 and <= 255 } && request.ChecksumSha256 is { Length: 64 } &&
           request.ChecksumSha256.All(character => character is >= '0' and <= '9' or >= 'a' and <= 'f');

    private bool ValidOptions()
        => _options.PartSizeBytes == 8 * 1024 * 1024 && _options.SessionLifetimeHours == 24 && _options.SignedPutUrlLifetimeMinutes == 15;

    private static bool ValidMimeType(string? value)
        => value is { Length: > 2 and <= 120 } && value.Count(character => character == '/') == 1;

    private static UploadCreateRequestDto Normalize(UploadCreateRequestDto request)
        => request with
        {
            Purpose = request.Purpose.Trim().ToUpperInvariant(),
            FileName = request.FileName.Trim(),
            MediaType = request.MediaType.Trim().ToLowerInvariant(),
            ChecksumSha256 = request.ChecksumSha256.Trim()
        };

    private static UploadServiceResult MapMutation(UploadMutationPersistenceResult result)
        => result.Status switch
        {
            UploadPersistenceStatus.Success => new(UploadServiceStatus.Success, ToDto(result.Session!)),
            UploadPersistenceStatus.Replayed => new(UploadServiceStatus.Replayed, ToDto(result.Session!)),
            UploadPersistenceStatus.NotFound => new(UploadServiceStatus.NotFound),
            UploadPersistenceStatus.ConcurrencyConflict => new(UploadServiceStatus.PreconditionFailed),
            UploadPersistenceStatus.Conflict => new(UploadServiceStatus.Conflict),
            UploadPersistenceStatus.StorageUnavailable => new(UploadServiceStatus.StorageUnavailable),
            _ => new(UploadServiceStatus.InvalidInput)
        };

    private static UploadSessionResponseDto ToDto(UploadSessionPersistenceView view)
        => new(view.Id, view.FileId, view.Status, view.PartSizeBytes, view.ExpiresAt, view.Version);

    private static FileMetadataResponseDto ToDto(FileMetadataPersistenceView view)
        => new(view.Id, view.Status == "VERIFIED" ? "VERIFIED" : view.Status == "FAILED" ? "FAILED" : "PENDING", view.ChecksumSha256, view.MediaType, view.SizeBytes, view.Version);

    private static string Fingerprint(string value)
        => Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(value))).ToLowerInvariant();
}

