            i.Evidence.All(e => e is not null && e.FileId != Guid.Empty &&
                (e.FromMilliseconds is null && e.ToMilliseconds is null || e.FromMilliseconds >= 0 && e.ToMilliseconds > e.FromMilliseconds)));
